package kr.campusrent;
import com.fasterxml.jackson.databind.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfSystemProperty;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import static kr.campusrent.RentalService.*;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(properties={"debug=false","logging.level.root=WARN","logging.level.org.springframework=WARN","logging.level.com.zaxxer.hikari=WARN"}) @Transactional @EnabledIfSystemProperty(named="oracle.integration",matches="true")
class RecommendationOracleTest {
 @Autowired RecommendationService recommendations;@Autowired RentalService rental;@Autowired JdbcTemplate db;ObjectMapper json=new ObjectMapper();Map<String,Object> admin=obj("id","1","role","admin"),student=obj("id","2","role","student");
 @Test void seededRulesAndDemoPermissionsExist(){assertEquals(7,db.queryForObject("SELECT COUNT(*) FROM USE_PURPOSE WHERE PURPOSE_CODE IN ('INTERVIEW','PRESENTATION','MEETING','ASSIGNMENT_VIDEO','CONTENT_VIDEO','JOB_INTERVIEW','STUDY')",Integer.class));assertTrue(db.queryForObject("SELECT COUNT(*) FROM PURPOSE_KEYWORD WHERE ENABLED_YN='Y'",Integer.class)>180);assertEquals(8,db.queryForObject("SELECT COUNT(*) FROM FACILITY_PURPOSE X JOIN FACILITY F ON F.FACILITY_ID=X.FACILITY_ID JOIN USE_PURPOSE P ON P.PURPOSE_ID=X.PURPOSE_ID WHERE F.FACILITY_CODE IN ('DEMO-ROOM01','DEMO-ROOM02','DEMO-STUDY01','DEMO-STUDIO01','DEMO-STUDIO02') AND P.PURPOSE_CODE IN ('CONTENT_VIDEO','JOB_INTERVIEW','STUDY')",Integer.class));assertNotNull(recommendations.rules());}
 @Test void keywordsCanBeEditedDisabledAndConflictChecked(){Map<String,Object> draft=obj("purposeId",4,"keyword","검증-"+UUID.randomUUID(),"mode","CONTAINS","effect","INCLUDE","priority",60,"enabled",true);long id=recommendations.save(null,json.valueToTree(draft),admin);draft.put("expected",new HashMap<>(draft));draft.put("enabled",false);recommendations.save(id,json.valueToTree(draft),admin);assertEquals("N",db.queryForObject("SELECT ENABLED_YN FROM PURPOSE_KEYWORD WHERE KEYWORD_ID=?",String.class,id));assertThrows(IllegalArgumentException.class,()->recommendations.save(id,json.valueToTree(draft),admin));}
 @Test void keywordManagementRequiresAdmin(){assertThrows(IllegalArgumentException.class,()->recommendations.management(student));assertThrows(IllegalArgumentException.class,()->recommendations.save(null,json.valueToTree(obj("purposeId",4,"keyword","임의","mode","CONTAINS","effect","INCLUDE","priority",20,"enabled",true)),student));}
 @Test void newPurposeCanBeSubmittedOnlyToAllowedFacility(){String day=LocalDate.now(KOREA).plusDays(17).toString();List<String> ids=rental.submit(json.valueToTree(Arrays.asList(obj("resourceId","F1","condition",obj("start",day+"T10:00","end",day+"T12:00","people",2,"use","면접 연습"),"originCode","PURPOSE","activity","모의 면접 2명"))),student);assertEquals("모의 면접 2명",db.queryForObject("SELECT ACTIVITY_TEXT FROM REQUEST_ITEM WHERE REQUEST_ITEM_ID=?",String.class,Long.valueOf(ids.get(0))));assertThrows(IllegalArgumentException.class,()->rental.submit(json.valueToTree(Arrays.asList(obj("resourceId","F1","condition",obj("start",day+"T13:00","end",day+"T14:00","people",2,"use","영상 콘텐츠 촬영")))),student));}
}
